// The emitter seam: an emitter turns the app model into framework files, and
// `writeGenerated` writes them under the ownership rule every framework shares.
//
// A generated file starts with GENERATED_HEADER. The generator rewrites a file
// only while that first line is still there; deleting the line hands the file
// to whoever edits it next, and the generator never touches it again.
//
// The written header also carries a hash of the body. A file edited without
// deleting the header no longer matches it: the generator leaves that file
// alone too, and reports it as modified, so a hand edit is never lost.

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';

import type { AppModel } from './app-spec.ts';
import type { ResourceIR } from './meta-ir.ts';

export const GENERATED_HEADER = '// @generated by gen:resources — delete this line to take ownership';

/** What a generated file renders, so a re-run can tell the app what its own copy is missing. */
export type FileSubject =
	| { kind: 'app' }
	| { kind: 'registry' }
	| { kind: 'dashboard' }
	| { kind: 'resource'; resource: string }
	| { kind: 'page'; resource: string };

export type EmittedFile = {
	/** POSIX path relative to the app root. */
	path: string;
	/** Full file content; its first line is GENERATED_HEADER (writeGenerated adds the hash). */
	content: string;
	subject?: FileSubject;
};

const HASHED_HEADER = /^(.*) \(body sha256:([0-9a-f]{12})\)$/;

function bodyHash(body: string): string {
	return createHash('sha256').update(body).digest('hex').slice(0, 12);
}

function split(content: string): [firstLine: string, body: string] {
	const newline = content.indexOf('\n');
	return newline === -1 ? [content, ''] : [content.slice(0, newline).replace(/\r$/, ''), content.slice(newline + 1)];
}

/** Hash of the body below the first line: what the stamped header records. */
export function generatedHash(content: string): string {
	return bodyHash(split(content)[1]);
}

/** The content as written: the header line stamped with the hash of the body below it. */
export function stampGenerated(content: string): string {
	const [, body] = split(content);
	return `${GENERATED_HEADER} (body sha256:${bodyHash(body)})\n${body}`;
}

/** owned: header deleted. modified: header kept, body edited since it was written. pristine: as generated. */
export function generatedState(content: string): 'owned' | 'modified' | 'pristine' {
	const [firstLine, body] = split(content);
	if (!firstLine.startsWith(GENERATED_HEADER)) return 'owned';
	const hashed = HASHED_HEADER.exec(firstLine);
	return hashed && hashed[1] === GENERATED_HEADER && hashed[2] !== bodyHash(body) ? 'modified' : 'pristine';
}

export interface Emitter {
	readonly name: string;
	emit(model: AppModel): EmittedFile[];
	/** URL path of a resource's list page. */
	route(resource: ResourceIR): string;
	/**
	 * Directories (relative to the app root) where a generated file that is no
	 * longer emitted gets removed, e.g. the route folder of a dropped table.
	 */
	readonly pruneRoots: readonly string[];
	/**
	 * Files the framework derives from the routes (relative to the app root).
	 * They are deleted whenever generated files change, so a type-check never
	 * sees a route that no longer exists; the framework writes them again.
	 */
	readonly derivedPaths?: readonly string[];
	/** The generated app SDK's input types, read for its filter inputs when present. */
	readonly sdkInputTypes?: string;
}

export type WriteReport = {
	/** Created or changed. */
	written: string[];
	/** Generated and already up to date. */
	unchanged: string[];
	/** Owned by the app (header removed): left alone. */
	skipped: string[];
	/** Edited by hand with the header still in place: left alone, so the edit isn't lost. */
	modified: string[];
	/** Generated files for resources that no longer exist. */
	removed: string[];
};

export function isGenerated(content: string): boolean {
	return generatedState(content) !== 'owned';
}

function toPosix(path: string): string {
	return path.split(sep).join('/');
}

function listFiles(root: string, dir: string): string[] {
	const abs = join(root, dir);
	if (!existsSync(abs)) return [];
	const out: string[] = [];
	for (const entry of readdirSync(abs, { withFileTypes: true })) {
		const rel = join(dir, entry.name);
		if (entry.isDirectory()) out.push(...listFiles(root, rel));
		else out.push(toPosix(rel));
	}
	return out;
}

function removeEmptyDirs(root: string, dir: string, stopAt: string) {
	let current = dir;
	while (current && current !== stopAt && current !== '.' && existsSync(join(root, current))) {
		if (readdirSync(join(root, current)).length > 0) return;
		rmdirSync(join(root, current));
		current = toPosix(dirname(current));
	}
}

/** Deletes the emitter's derived paths after a change; returns the ones that existed. */
export function clearDerived(root: string, paths: readonly string[] = [], options: { dryRun?: boolean } = {}): string[] {
	const cleared = paths.filter((path) => existsSync(join(root, path)));
	if (!options.dryRun) for (const path of cleared) rmSync(join(root, path), { recursive: true, force: true });
	return cleared;
}

export function writeGenerated(
	root: string,
	files: EmittedFile[],
	pruneRoots: readonly string[],
	options: { dryRun?: boolean } = {},
): WriteReport {
	const report: WriteReport = { written: [], unchanged: [], skipped: [], modified: [], removed: [] };
	const emitted = new Set(files.map((file) => file.path));

	for (const file of files) {
		if (!isGenerated(file.content)) throw new Error(`Emitter produced ${file.path} without the generated header.`);
		const content = stampGenerated(file.content);
		const abs = join(root, file.path);
		if (existsSync(abs)) {
			const current = readFileSync(abs, 'utf8');
			const state = generatedState(current);
			if (state !== 'pristine') {
				report[state === 'owned' ? 'skipped' : 'modified'].push(file.path);
				continue;
			}
			if (current === content) {
				report.unchanged.push(file.path);
				continue;
			}
		}
		if (!options.dryRun) {
			mkdirSync(dirname(abs), { recursive: true });
			writeFileSync(abs, content);
		}
		report.written.push(file.path);
	}

	for (const pruneRoot of pruneRoots) {
		for (const path of listFiles(root, pruneRoot)) {
			if (emitted.has(path)) continue;
			const abs = join(root, path);
			const state = generatedState(readFileSync(abs, 'utf8'));
			if (state === 'owned') continue;
			if (state === 'modified') {
				report.modified.push(path);
				continue;
			}
			if (!options.dryRun) {
				rmSync(abs);
				removeEmptyDirs(root, toPosix(dirname(path)), toPosix(relative(root, join(root, pruneRoot))));
			}
			report.removed.push(path);
		}
	}

	for (const list of Object.values(report)) list.sort();
	return report;
}
